-- Reverse of apply.sql: parser_config back to '{}' (one transaction), then the backfilled dates back to NULL in batches. Generated by Build-Sql.py.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
DO $do$ DECLARE k int; BEGIN
  UPDATE feeds SET parser_config = '{}'::jsonb WHERE publisher_id = 968 AND feed_url = 'https://www.hani.co.kr/rss/' AND parser_config = '{"undated": "fetch_time"}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '968: % rows, expected 1', k; END IF;
  UPDATE feeds SET parser_config = '{}'::jsonb WHERE publisher_id = 3138 AND feed_url = 'https://feeds.leparisien.fr/leparisien/rss' AND parser_config = '{"undated": "fetch_time"}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '3138: % rows, expected 1', k; END IF;
  UPDATE feeds SET parser_config = '{}'::jsonb WHERE publisher_id = 1047 AND feed_url = 'https://www.presstv.ir/rss.xml' AND parser_config = '{"undated": "fetch_time"}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '1047: % rows, expected 1', k; END IF;
  UPDATE feeds SET parser_config = '{}'::jsonb WHERE publisher_id = 1015 AND feed_url = 'https://kathmandupost.com/rss' AND parser_config = '{"undated": "fetch_time"}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '1015: % rows, expected 1', k; END IF;
  UPDATE feeds SET parser_config = '{}'::jsonb WHERE publisher_id = 171 AND feed_url = 'https://www.elkhabar.com/feed' AND parser_config = '{"undated": "fetch_time"}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '171: % rows, expected 1', k; END IF;
END $do$;
COMMIT;
CREATE TEMP TABLE batch_ids AS
  SELECT id, ((row_number() OVER (ORDER BY id)) - 1) / 500 AS b FROM articles WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND published_at = fetched_at;
SET statement_timeout = '15s';
SELECT format('UPDATE articles a SET published_at = NULL FROM batch_ids i WHERE i.b = %s AND a.id = i.id AND a.published_at = a.fetched_at', b), 'SELECT pg_sleep(4)'
  FROM generate_series(0, coalesce((SELECT max(b) FROM batch_ids), -1)) b ORDER BY b
\gexec
RESET statement_timeout;
SELECT 'undated|' || publisher_id || '|' || count(*) || '|in window=' || count(*) FILTER (WHERE fetched_at > now() - interval '14 days')
  FROM articles WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND published_at IS NULL GROUP BY publisher_id ORDER BY publisher_id;
